// Windows and their menus. A window on the desktop is a window of the computer where there is a display (graphics_surfaces.cpp):
// the computer frames, moves, sizes and stacks it, and tells what happened through bb_gui_window_event. Where there is none,
// windows are drawn inside of the window of the program, in the order that they were last activated in: the one that was
// activated last is on top.

#include "gui_internal.hpp"
#include "memory.h"
#include "runtime_internal.h"

namespace bb::gui {
	static thread_local int active = 0;

	int active_window()
	{
		return gadget_of(active) ? active : 0;
	}

	void post_to(int kind, int handle, int data, int x, int y, int z)
	{
		bb_event_post(kind, data, x, y, z, handle);
	}

	void post_action(int handle, int data, int x, int y)
	{
		post_to(event_gadget_action, handle, data, x, y, 0);
	}

	// Puts the window on top of the ones next to it.
	static void raise(int handle)
	{
		gadget* g = gadget_of(handle);
		if (!g) {
			return;
		}
		gadget* parent = gadget_of(g->parent);
		if (!parent) {
			return;
		}
		for (uint32_t k = 0; k < parent->kids.size; k++) {
			if (parent->kids[k] == handle) {
				for (uint32_t m = k + 1; m < parent->kids.size; m++) {
					parent->kids[m - 1] = parent->kids[m];
				}
				parent->kids[parent->kids.size - 1] = handle;
				break;
			}
		}
	}

	void set_active_window(int handle, bool post)
	{
		if (handle && !gadget_of(handle)) {
			handle = 0;
		}
		if (handle == active) {
			return;
		}
		active = handle;
		if (handle) {
			raise(handle);
			if (post) {
				post_to(event_window_active, handle, 0);
			}
		}
		dirty();
	}

	int window_menu_root(int window)
	{
		gadget* g = gadget_of(window);
		if (!g) {
			return 0;
		}
		if (!g->menu) {
			menu* m = new menu();
			m->used = true;
			m->text = copy_string("");
			m->tag  = -1;
			menus.push(m);
			g->menu = int(menus.size) + menu_base;
		}
		return g->menu;
	}

	void free_menu_tree(int handle)
	{
		menu* m = menu_of(handle);
		if (!m) {
			return;
		}
		while (m->kids.size) {
			free_menu_tree(m->kids[m->kids.size - 1]);
		}
		if (menu* parent = menu_of(m->parent)) {
			for (uint32_t k = 0; k < parent->kids.size; k++) {
				if (parent->kids[k] == handle) {
					for (uint32_t n = k + 1; n < parent->kids.size; n++) {
						parent->kids[n - 1] = parent->kids[n];
					}
					parent->kids.size--;
					break;
				}
			}
		}
		bb_free(m->text);
		m->text = nullptr;
		m->kids.release();
		m->used = false;
		dirty();
	}

	// Windows of the computer are minimized, maximized and restored by it, which it then tells (bb_gui_window_event).
	static bool native_state(gadget& g, int state)
	{
		if (!g.surface) {
			return false;
		}
		bb_gui_window_state(g.surface, state);
		return true;
	}

	static void maximize_window(gadget& g, int handle)
	{
		if (native_state(g, 2)) {
			return;
		}
		if (!g.maximized && !g.minimized) {
			g.restore_x = g.x;
			g.restore_y = g.y;
			g.restore_w = g.w;
			g.restore_h = g.h;
		}
		g.minimized = false;
		g.maximized = true;
		gadget* parent = gadget_of(g.parent);
		int     pw = parent ? parent->cw : g.w, ph = parent ? parent->ch : g.h;
		set_shape(handle, 0, 0, pw, ph);
	}
} // namespace bb::gui

using namespace bb::gui;

extern "C" {

int32_t bb_create_window(const char* text, int32_t x, int32_t y, int32_t w, int32_t h, int32_t group, int32_t style)
{
	int handle = create_gadget(K_WINDOW, style, group, "CreateWindow");
	gadget* g  = gadget_of(handle);
	set_string(g->text, text);
	// A window on the desktop is a window of the computer, where one can be made. Its size is taken as if it had one until it
	// is known whether it does, as the frame and the title are the computer's then and not part of the size.
	bool native = gadget_of(g->parent) && (gadget_of(g->parent)->kind == K_DESKTOP);
	int  cw = w, ch = h;
	g->surface = native ? -1 : 0;
	if (style & 32) {
		int l, t, r, b;
		window_decoration(*g, &l, &t, &r, &b);
		w += l + r;
		h += t + b;
	}
	g->surface = 0;
	if (native) {
		int flags = ((style & 2) ? 1 : 0) | ((style & 1) ? 0 : 2) | ((style & 16) ? 4 : 0);
		g->surface = bb_gui_window_open(g->text, x, y, w, h, flags);
		if (!g->surface && (style & 32)) {
			int l, t, r, b;
			window_decoration(*g, &l, &t, &r, &b);
			w = cw + l + r;
			h = ch + t + b;
		}
	}
	g->x = x;
	g->y = y;
	g->w = w;
	g->h = h;
	update_client(handle);
	lock_layout(*g);
	g->visible = true;
	set_active_window(handle, true);
	return handle;
}

int32_t bb_active_window(void)
{
	return active_window();
}

void bb_activate_window(int32_t handle)
{
	gadget* g = need_kind(handle, K_WINDOW, "ActivateWindow");
	if (g->surface) {
		bb_gui_window_raise(g->surface);
	}
	set_active_window(handle, true);
}

void bb_update_window_menu(int32_t handle)
{
	need_kind(handle, K_WINDOW, "UpdateWindowMenu");
	dirty();
}

void bb_set_status_text(int32_t handle, const char* text)
{
	gadget* g = need_kind(handle, K_WINDOW, "SetStatusText");
	set_string(g->status, text);
	dirty();
}

void bb_set_min_window_size(int32_t handle, int32_t w, int32_t h)
{
	gadget* g = need_kind(handle, K_WINDOW, "SetMinWindowSize");
	g->min_w  = w >= 0 ? w : g->w;
	g->min_h  = h >= 0 ? h : g->h;
	if (g->surface) {
		bb_gui_window_min_size(g->surface, g->min_w, g->min_h);
	}
	if ((g->w < g->min_w) || (g->h < g->min_h)) {
		set_shape(handle, g->x, g->y, g->w < g->min_w ? g->min_w : g->w, g->h < g->min_h ? g->min_h : g->h);
	}
}

void bb_minimize_window(int32_t handle)
{
	gadget* g = need_kind(handle, K_WINDOW, "MinimizeWindow");
	if (native_state(*g, 1)) {
		return;
	}
	if (!g->minimized && !g->maximized) {
		g->restore_x = g->x;
		g->restore_y = g->y;
		g->restore_w = g->w;
		g->restore_h = g->h;
	}
	g->minimized = true;
	g->maximized = false;
	dirty();
}

void bb_maximize_window(int32_t handle)
{
	gadget* g = need_kind(handle, K_WINDOW, "MaximizeWindow");
	if (g->style & 2) {
		maximize_window(*g, handle);
	} else if (!(g->style & 1)) {
		maximize_window(*g, handle);
	} else {
		// Windows that can't be sized still become as big as the desktop when this is asked for.
		maximize_window(*g, handle);
	}
	dirty();
}

void bb_restore_window(int32_t handle)
{
	gadget* g = need_kind(handle, K_WINDOW, "RestoreWindow");
	if (native_state(*g, 0)) {
		return;
	}
	if (g->minimized || g->maximized) {
		g->minimized = g->maximized = false;
		set_shape(handle, g->restore_x, g->restore_y, g->restore_w, g->restore_h);
	}
	dirty();
}

int32_t bb_window_minimized(int32_t handle)
{
	return need_kind(handle, K_WINDOW, "WindowMinimized")->minimized ? 1 : 0;
}

int32_t bb_window_maximized(int32_t handle)
{
	return need_kind(handle, K_WINDOW, "WindowMaximized")->maximized ? 1 : 0;
}

int32_t bb_window_menu(int32_t handle)
{
	need_kind(handle, K_WINDOW, "WindowMenu");
	return window_menu_root(handle);
}

// What the computer did with a window of the GUI (graphics_input.cpp): 1 moved it to a, b; 2 sized it to a by b; 3 was asked to
// close it; 4 gave it the focus; 5 took the focus; 6 minimized it; 7 maximized it; 8 restored it; 9 the mouse came in; 10 it left.
// The program is told the way BlitzPlus tells: $801 and $802 for the shape, $803 for the close box, $804 for the focus.
void bb_gui_window_event(int32_t window, int32_t kind, int32_t a, int32_t b)
{
	int     handle = gadget_of_surface(window);
	gadget* g      = gadget_of(handle);
	if (!g) {
		return;
	}
	switch (kind) {
	case 1:
		if ((g->x != a) || (g->y != b)) {
			g->x = a;
			g->y = b;
			if (!g->minimized && !g->maximized) {
				lock_layout(*g);
			}
			if (g->visible) {
				post_to(event_window_move, handle, 0, a, b);
			}
			dirty();
		}
		break;
	case 2:
		if ((g->w != a) || (g->h != b)) {
			g->w = a > 0 ? a : 1;
			g->h = b > 0 ? b : 1;
			update_client(handle);
			if (!g->minimized && !g->maximized) {
				lock_layout(*g);
			}
			if (g->visible) {
				post_to(event_window_size, handle, 0, g->w, g->h);
			}
			dirty();
		}
		break;
	case 3:
		post_to(event_window_close, handle, 0);
		break;
	case 4:
		set_active_window(handle, true);
		break;
	case 6:
		if (!g->minimized && !g->maximized) {
			g->restore_x = g->x;
			g->restore_y = g->y;
			g->restore_w = g->w;
			g->restore_h = g->h;
		}
		g->minimized = true;
		g->maximized = false;
		dirty();
		break;
	case 7:
		if (!g->minimized && !g->maximized) {
			g->restore_x = g->x;
			g->restore_y = g->y;
			g->restore_w = g->w;
			g->restore_h = g->h;
		}
		g->minimized = false;
		g->maximized = true;
		dirty();
		break;
	case 8:
		g->minimized = g->maximized = false;
		dirty();
		break;
	default:
		break;
	}
}

////////////////////////////////////////////////////////////////////////////////
// Menus
////////////////////////////////////////////////////////////////////////////////
static menu* need_menu(int32_t handle, const char* what)
{
	menu* m = menu_of(handle);
	if (!m) {
		char message[128];
		snprintf(message, sizeof(message), "%s: the menu does not exist.", what);
		gui_error(message);
	}
	return m;
}

int32_t bb_create_menu(const char* text, int32_t tag, int32_t parent)
{
	menu* p = need_menu(parent, "CreateMenu");
	menu* m = new menu();
	m->used   = true;
	m->text   = copy_string(text);
	m->tag    = tag;
	m->parent = parent;
	menus.push(m);
	int handle = int(menus.size) + menu_base;
	p->kids.push(handle);
	dirty();
	return handle;
}

void bb_set_menu_text(int32_t handle, const char* text)
{
	set_string(need_menu(handle, "SetMenuText")->text, text);
	dirty();
}

void bb_check_menu(int32_t handle)
{
	need_menu(handle, "CheckMenu")->checked = true;
	dirty();
}

void bb_uncheck_menu(int32_t handle)
{
	need_menu(handle, "UncheckMenu")->checked = false;
	dirty();
}

void bb_enable_menu(int32_t handle)
{
	need_menu(handle, "EnableMenu")->enabled = true;
	dirty();
}

void bb_disable_menu(int32_t handle)
{
	need_menu(handle, "DisableMenu")->enabled = false;
	dirty();
}

int32_t bb_menu_checked(int32_t handle)
{
	return need_menu(handle, "MenuChecked")->checked ? 1 : 0;
}

int32_t bb_menu_enabled(int32_t handle)
{
	return need_menu(handle, "MenuEnabled")->enabled ? 1 : 0;
}

const char* bb_menu_text(int32_t handle)
{
	return string_result(need_menu(handle, "MenuText")->text);
}
}
